+    return '';
+  } else if (allowedAuthProviders.length !== configuredAuthProviders.length) {
+    const prisma = new PrismaService();
+    await prisma.infraConfig.update({
+      where: { name: InfraConfigEnum.VITE_ALLOWED_AUTH_PROVIDERS },
