+    // directly to them.
+    for item in items {
+        let loc = match item {
+            Item::Tag(_) => continue,
+            Item::Asset(.., loc) => loc,
+            Item::Document(.., loc) => loc,
+        };
+        anchors.insert(*loc, EcoString::new());
+    }
