+    pub fn link_targets(&self) -> FxHashSet<Location> {
+        LinkElem::find_destinations(self)
+            .chain(self.frame_link_targets.iter().copied())
+            .collect()
+    }
+
+    /// Returns the locations that the HTML document links to via
