issue.body:
So, I am trying to get a correspondence between input and output in a network.
It works well when there are no `repeat` layers in the network, otherwise, the visitor does nothing.

Is there an easy way to fix this?

Here's an example that showcases the problem:

``` c++
#include <dlib/dnn.h>

using namespace std;
using namespace dlib;

template <typename SUBNET>
using conblock = relu<bn_con<add_layer<con_<16, 3, 3, 2, 2, 1, 1>, SUBNET>>>;

using net_type_1 = loss_binary_log_per_pixel<con<1, 1, 1, 1, 1,conblock<conblock<conblock<tag1<input_rgb_image>>>>>>;
using net_type_2 = loss_binary_log_per_pixel<con<1, 1, 1, 1, 1,repeat<3, conblock, tag1<input_rgb_image>>>>;

int main(const int argc, const char** argv)
{
    matrix<rgb_pixel> image(256, 256);
    net_type_1 net_1;
    net_type_2 net_2;
    net_1(image);
    net_2(image);
    point p(64, 64);
    cout << input_tensor_to_output_tensor(net_1, p) << endl;  // ouputs (8, 8), as expected
    cout << input_tensor_to_output_tensor(net_2, p) << endl;  // outputs (64, 64)
}
```

